---Converts a color source to an RGBA float color.
---@param source UguiColorSource The color source.
---@return UguiRGBAF # The converted color.
ugui.color_source_to_rgbaf = function(source)
    if math.type(source) == 'integer' then
        return {
            r = ((source >> 24) & 0xFF) / 255.0,
            g = ((source >> 16) & 0xFF) / 255.0,
            b = ((source >> 8) & 0xFF) / 255.0,
            a = (source & 0xFF) / 255.0,
        }
    end

    if type(source) == 'string' then
        local r = tonumber(source:sub(2, 3), 16)
        local g = tonumber(source:sub(4, 5), 16)
        local b = tonumber(source:sub(6, 7), 16)
        local a = tonumber(source:sub(8, 9), 16)
        return {
            r = (r or 0) / 255.0,
            g = (g or 0) / 255.0,
            b = (b or 0) / 255.0,
            a = (a or 255) / 255.0,
        }
    end

    if source[1] or source[2] or source[3] or source[4] then
        if math.type(source[1]) == 'float' or math.type(source[2]) == 'float' or math.type(source[3]) == 'float' then
            return {
                r = source[1] or 0.0,
                g = source[2] or 0.0,
                b = source[3] or 0.0,
                a = source[4] or 1.0,
            }
        end

        return {
            r = (source[1] or 0) / 255.0,
            g = (source[2] or 0) / 255.0,
            b = (source[3] or 0) / 255.0,
            a = (source[4] or 255) / 255.0,
        }
    end

    if math.type(source.r) == 'float' or math.type(source.g) == 'float' or math.type(source.b) == 'float' then
        return {
            r = source.r or 0.0,
            g = source.g or 0.0,
            b = source.b or 0.0,
            a = source.a or 1.0,
        }
    end

    if math.type(source.r) == 'integer' or math.type(source.g) == 'integer' or math.type(source.b) == 'integer' then
        return {
            r = (source.r or 0) / 255.0,
            g = (source.g or 0) / 255.0,
            b = (source.b or 0) / 255.0,
            a = (source.a or 255) / 255.0,
        }
    end

    if type(source) == 'table' then
        return {r = 0.0, g = 0.0, b = 0.0, a = 1.0}
    end

    error('Invalid color source: ' .. tostring(source), 2)
end

---Converts a `UguiColorSource` to an `UguiRGBA8`.
---@param source UguiColorSource The color source.
---@return UguiRGBA8 color
ugui.color_source_to_rgba8 = function(source)
    local color = ugui.color_source_to_rgbaf(source)
    return {
        r = math.tointeger(math.floor(color.r * 255.0 + 0.5)),
        g = math.tointeger(math.floor(color.g * 255.0 + 0.5)),
        b = math.tointeger(math.floor(color.b * 255.0 + 0.5)),
        a = math.tointeger(math.floor(color.a * 255.0 + 0.5)),
    }
end

---Inverts the RGB channels of a color source while preserving its alpha.
---@param source UguiColorSource The color source.
---@return UguiRGBAF # The inverted color.
ugui.invert_color = function(source)
    local color = ugui.color_source_to_rgbaf(source)
    return {
        r = 1.0 - color.r,
        g = 1.0 - color.g,
        b = 1.0 - color.b,
        a = color.a,
    }
end

---Converts a color source to the painter API's color table type.
---@param source ColorSource The color source.
---@return PainterColorTable # The converted color.
ugui.internal.color_source_to_painter_color = function(source)
    local color = ugui.color_source_to_rgbaf(source)
    return {
        r = color.r,
        g = color.g,
        b = color.b,
        a = color.a,
    }
end

---Converts an RGBA float color to the painter API's color table type.
---@param color UguiRGBAF
---@return PainterColorTable
ugui.internal.rgbaf_to_painter_color = function(color)
    return {
        r = color.r,
        g = color.g,
        b = color.b,
        a = color.a,
    }
end

---Converts an RGBA float color to HSV components.
---@param color UguiRGBAF
---@return number hue
---@return number saturation
---@return number value
ugui.internal.rgbaf_to_hsv = function(color)
    local max_channel = math.max(color.r, color.g, color.b)
    local min_channel = math.min(color.r, color.g, color.b)
    local delta = max_channel - min_channel
    local hue = 0

    if delta > 0 then
        if max_channel == color.r then
            hue = ((color.g - color.b) / delta) % 6
        elseif max_channel == color.g then
            hue = (color.b - color.r) / delta + 2
        else
            hue = (color.r - color.g) / delta + 4
        end
        hue = hue / 6
    end

    local saturation = max_channel == 0 and 0 or delta / max_channel
    return hue, saturation, max_channel
end

---Converts HSV components to an RGBA float color without alpha.
---@param hue number
---@param saturation number
---@param value number
---@return UguiRGBAF
ugui.internal.hsv_to_rgbaf = function(hue, saturation, value)
    local sector = (hue % 1) * 6
    local chroma = value * saturation
    local secondary = chroma * (1 - math.abs(sector % 2 - 1))
    local offset = value - chroma
    local r, g, b

    if sector < 1 then
        r, g, b = chroma, secondary, 0
    elseif sector < 2 then
        r, g, b = secondary, chroma, 0
    elseif sector < 3 then
        r, g, b = 0, chroma, secondary
    elseif sector < 4 then
        r, g, b = 0, secondary, chroma
    elseif sector < 5 then
        r, g, b = secondary, 0, chroma
    else
        r, g, b = chroma, 0, secondary
    end

    return {r = r + offset, g = g + offset, b = b + offset}
end

---Copies an RGBA float color and defaults its alpha to 1.
---@param color UguiRGBAF
---@return UguiRGBAF
ugui.internal.copy_color = function(color)
    return {
        r = color.r,
        g = color.g,
        b = color.b,
        a = color.a or 1,
    }
end

---Inflates a rectangle around its center by the specified amount.
---@param rectangle UguiRect The rectangle.
---@param amount number The amount to inflate the rectangle by.
---@return UguiRect rectangle
ugui.internal.inflate_rect = function(rectangle, amount)
    return {
        x = rectangle.x - amount,
        y = rectangle.y - amount,
        width = rectangle.width + amount * 2,
        height = rectangle.height + amount * 2,
    }
end

---@param point UguiVector2
---@param rect UguiRect
---@return boolean inside
ugui.internal.point_in_rect = function(point, rect)
    return point.x >= rect.x and point.x <= rect.x + rect.width and
        point.y >= rect.y and point.y <= rect.y + rect.height
end

---@param point UguiVector2
---@param circle UguiRect
---@return boolean inside
ugui.internal.point_in_circle = function(point, circle)
    local radius = circle.width / 2
    local dx = point.x - (circle.x + radius)
    local dy = point.y - (circle.y + radius)
    return dx * dx + dy * dy <= radius * radius
end

---Asserts that the specified condition is true, printing the stacktrace if it's false.
---@param condition boolean
---@param message string
ugui.internal.assert = function(condition, message)
    if condition then
        return
    end
    print(debug.traceback())
    assert(condition, message)
end

---Returns the sign of a number.
---@param value number
---@return -1|0|1
ugui.internal.sign = function(value)
    if value > 0 then
        return 1
    elseif value < 0 then
        return -1
    else
        return 0
    end
end

---Deeply clones a table.
---@param obj table The table to clone.
---@param seen table? Internal. Pass nil as a caller.
---@return table A cloned instance of the table.
ugui.internal.deep_clone = function(obj, seen)
    if type(obj) ~= 'table' then return obj end
    if seen and seen[obj] then return seen[obj] end
    local s = seen or {}
    local res = setmetatable({}, getmetatable(obj))
    s[obj] = res
    for k, v in pairs(obj) do
        res[ugui.internal.deep_clone(k, s)] = ugui.internal.deep_clone(
            v, s)
    end
    return res
end

---Merges two tables deeply, mutating the second table with the first table's values, giving precedence to the first table's values.
---@param a table The override table, whose values take precedence.
---@param b table The source and target table, mutated in-place.
---@return function A function that rolls back all changes made to b.
ugui.internal.deep_merge = function(a, b)
    local rollback_ops = {}

    local function merge(t1, t2)
        for key, value in pairs(t1) do
            if type(value) == 'table' and type(t2[key]) == 'table' then
                merge(value, t2[key])
            else
                local prev = t2[key]
                t2[key] = value
                local t2_ref = t2
                local k = key
                rollback_ops[#rollback_ops + 1] = function()
                    t2_ref[k] = prev
                end
            end
        end
    end

    merge(a, b)

    return function()
        for i = #rollback_ops, 1, -1 do
            rollback_ops[i]()
        end
    end
end


---Removes a range of characters from a string.
---@param string string The string to remove characters from.
---@param start_index integer The index of the first character to remove.
---@param end_index integer The index of the last character to remove.
---@return string # A new string with the characters removed.
ugui.internal.remove_range = function(string, start_index, end_index)
    if start_index > end_index then
        start_index, end_index = end_index, start_index
    end
    return string.sub(string, 1, start_index - 1) .. string.sub(string, end_index)
end

---Removes the character at the specified index from a string.
---@param string string The string to remove the character from.
---@param index integer The index of the character to remove.
---@return string # A new string with the character removed.
ugui.internal.remove_at = function(string, index)
    if index == 0 then
        return string
    end
    return string:sub(1, index - 1) .. string:sub(index + 1, string:len())
end

---Inserts a string into another string at the specified index.
---@param string string The original string to insert the other string into.
---@param string2 string The other string.
---@param index integer The index into the first string to begin inserting the second string at.
---@return string # A new string with the other string inserted.
ugui.internal.insert_at = function(string, string2, index)
    index = math.max(1, math.min(index, #string + 1))
    return string:sub(1, index - 1) .. string2 .. string:sub(index)
end

---Gets the digit at a specific index in a number with a specific padded length.
---@param value integer The number.
---@param length integer The number's padded length (number of digits).
---@param index integer The index to get digit from.
---@return integer # The digit at the specified index.
ugui.internal.get_digit = function(value, length, index)
    return math.floor(value / math.pow(10, length - index)) % 10
end

---Sets the digit at a specific index in a number with a specific padded length.
---@param value integer The number.
---@param length integer The number's padded length (number of digits).
---@param digit_value integer The new digit value.
---@param index integer The index to get digit from.
---@return integer # The new number.
ugui.internal.set_digit = function(value, length, digit_value, index)
    local old_digit_value = ugui.internal.get_digit(value, length, index)
    local new_value = value + (digit_value - old_digit_value) * math.pow(10, length - index)
    local max = math.pow(10, length)
    return (new_value + max) % max
end

---Sets a range of digits in a padded number.
---@param value integer The number.
---@param length integer The number's padded length.
---@param digits string The digits to insert.
---@param index integer The starting index (1 = leftmost).
---@return integer
ugui.internal.set_digit_range = function(value, length, digits, index)
    local count = #digits
    local digits_value = tonumber(digits)

    local insert_pow = math.pow(10, length - index - count + 1)
    local range_pow = math.pow(10, count)

    -- extract existing digits in that range
    local old_range = math.floor(value / insert_pow) % range_pow

    -- replace them
    local new_value = value + (digits_value - old_range) * insert_pow

    local max = math.pow(10, length)
    return (new_value + max) % max
end

---Remaps a value from one range to another.
---@param value number The value.
---@param from1 number The lower bound of the first range.
---@param to1 number The upper bound of the first range.
---@param from2 number The lower bound of the second range.
---@param to2 number The upper bound of the second range.
---@return number # The new remapped value.
ugui.internal.remap = function(value, from1, to1, from2, to2)
    return (value - from1) / (to1 - from1) * (to2 - from2) + from2
end

---Returns scene children in stable z-index order without reordering the placement array.
---@param node SceneNode|SceneRoot
---@return SceneNode[]
ugui.internal.get_sorted_scene_children = function(node)
    if not node.sorted_children then
        local children = node.children
        local sorted = true
        for i = 2, #children do
            local previous = children[i - 1]
            local current = children[i]
            local previous_z_index = previous.control.z_index or 0
            local current_z_index = current.control.z_index or 0
            if current_z_index < previous_z_index
                or (current_z_index == previous_z_index and current.order < previous.order) then
                sorted = false
                break
            end
        end

        if sorted then
            node.sorted_children = children
        else
            local sorted_children = {}
            for i = 1, #children do
                sorted_children[i] = children[i]
            end
            table.sort(sorted_children, function(a, b)
                local a_z_index = a.control.z_index or 0
                local b_z_index = b.control.z_index or 0
                if a_z_index == b_z_index then
                    return a.order < b.order
                end
                return a_z_index < b_z_index
            end)
            node.sorted_children = sorted_children
        end
    end
    return node.sorted_children
end

---Traverses a scene tree depth-first.
---@param node SceneNode
---@param callback fun(node: SceneNode): boolean? Return false to stop traversal early.
---@param reverse boolean? Traverse in reverse draw order.
---@return boolean completed Whether the traversal completed without being stopped.
ugui.internal.foreach_node = function(node, callback, reverse)
    local children = ugui.internal.get_sorted_scene_children(node)
    if reverse then
        for i = #children, 1, -1 do
            if not ugui.internal.foreach_node(children[i], callback, reverse) then
                return false
            end
        end
        return callback(node) ~= false
    end

    if callback(node) == false then
        return false
    end
    for i = 1, #children do
        if not ugui.internal.foreach_node(children[i], callback, false) then
            return false
        end
    end
    return true
end

---Traverses all nodes in the current scene, excluding the virtual root.
---@param callback fun(node: SceneNode): boolean? Return false to stop traversal early.
---@param reverse boolean? Traverse in reverse draw order.
---@return boolean completed Whether the traversal completed without being stopped.
ugui.internal.foreach_scene_node = function(callback, reverse)
    local children = ugui.internal.get_sorted_scene_children(ugui.internal.scene_root)
    if reverse then
        for i = #children, 1, -1 do
            if not ugui.internal.foreach_node(children[i], callback, true) then
                return false
            end
        end
    else
        for i = 1, #children do
            if not ugui.internal.foreach_node(children[i], callback, false) then
                return false
            end
        end
    end
    return true
end

---Finds a scene node by the UID of its control.
---@param uid UID?
---@return SceneNode?
ugui.internal.find_node = function(uid)
    if uid == nil then
        return nil
    end
    return ugui.internal.scene_nodes_by_uid[uid]
end

---Checks whether a point is inside every clipping ancestor of a node.
---@param point UguiVector2
---@param node SceneNode
---@return boolean
ugui.internal.is_point_inside_clip_ancestors = function(point, node)
    local ancestor = node.parent
    while ancestor and ancestor ~= ugui.internal.scene_root do
        local control = ancestor.control
        if control.clip_children and not ugui.internal.point_in_rect(
                point,
                control.render_rect
            ) then
            return false
        end
        ancestor = ancestor.parent
    end
    return true
end

---Checks a scene node's own bounds and all clipping ancestor bounds.
---@param point UguiVector2
---@param node SceneNode
---@return boolean
ugui.internal.hittest_node = function(point, node)
    return ugui.internal.hittest(point, node.control)
        and ugui.internal.is_point_inside_clip_ancestors(point, node)
end


local function render_rectangle_from_parent(rectangle, parent_rectangle)
    return {
        x = parent_rectangle.x + rectangle.x,
        y = parent_rectangle.y + rectangle.y,
        width = rectangle.width,
        height = rectangle.height,
    }
end

local function get_parent_render_rectangle(parent)
    if parent == nil or parent == ugui.internal.scene_root then
        return {x = 0, y = 0, width = 0, height = 0}
    end
    return assert(parent.control.render_rect)
end

---Computes a control's absolute rectangle using its current parent.
---@param control UguiControl
---@return UguiRect
ugui.internal.compute_render_rect = function(control)
    local parent = ugui.internal.current_parent
    return render_rectangle_from_parent(control.rectangle, get_parent_render_rectangle(parent))
end


---Checks whether a point is inside the control's custom hit region, or its render rectangle by default.
---@param point UguiVector2
---@param control UguiControl
---@return boolean
ugui.internal.hittest = function(point, control)
    if control.hittest then
        return control.hittest(control, point)
    end
    return ugui.internal.point_in_rect(point, control.render_rect)
end

---Recomputes a placed node and its descendants after a local rectangle changes.
---@param control UguiControl
ugui.internal.update_render_rect = function(control)
    local node = ugui.internal.find_node(control.uid)
    if not node then
        return
    end

    local function update_node(current_node, parent_rectangle)
        local current_control = current_node.control
        local render_rect = render_rectangle_from_parent(
            current_control.rectangle,
            parent_rectangle
        )
        current_control.render_rect = render_rect
        for i = 1, #current_node.children do
            update_node(current_node.children[i], render_rect)
        end
    end

    update_node(node, get_parent_render_rectangle(node.parent))
end


---Limits a value to a range.
---@param value number The value.
---@param min number The lower bound.
---@param max number The upper bound.
---@return number # The new limited value.
ugui.internal.clamp = function(value, min, max)
    return math.max(math.min(value, max), min)
end

