    ---Draws an icon with the specified parameters.
    ---@param rectangle UguiRect The icon's bounds.
    ---@param color UguiColorSource? The icon's fill color.
    ---@param key string The icon's identifier.
    draw_icon = function(rectangle, color, key)
        if not color then
            ugui.internal.painter:begin_path()
            ugui.internal.painter:rect(ugui.internal.rect_to_painter_rect(rectangle))
            ugui.internal.painter:fill({r = 1, g = 0, b = 0, a = 1})
            return
        end

        local p = ugui.internal.painter
        local painter_color = ugui.internal.color_source_to_painter_color(color)
        local center_x = rectangle.x + rectangle.width / 2
        local center_y = rectangle.y + rectangle.height / 2
        local arrow_extent = math.min(rectangle.width, rectangle.height) * 0.27
        local half_width = arrow_extent
        local half_height = arrow_extent
        local point_extent = arrow_extent * 0.75

        if key == 'arrow_left' then
            p:begin_path()
            p:move_to(center_x - point_extent, center_y)
            p:line_to(center_x + point_extent, center_y - half_height)
            p:line_to(center_x + point_extent, center_y + half_height)
            p:close_path()
            p:fill(painter_color)
        elseif key == 'arrow_right' then
            p:begin_path()
            p:move_to(center_x + point_extent, center_y)
            p:line_to(center_x - point_extent, center_y - half_height)
            p:line_to(center_x - point_extent, center_y + half_height)
            p:close_path()
            p:fill(painter_color)
        elseif key == 'arrow_up' then
            p:begin_path()
            p:move_to(center_x, center_y - point_extent)
            p:line_to(center_x + half_width, center_y + point_extent)
            p:line_to(center_x - half_width, center_y + point_extent)
            p:close_path()
            p:fill(painter_color)
        elseif key == 'arrow_down' then
            p:begin_path()
            p:move_to(center_x, center_y + point_extent)
            p:line_to(center_x + half_width, center_y - point_extent)
            p:line_to(center_x - half_width, center_y - point_extent)
            p:close_path()
            p:fill(painter_color)
        elseif key == 'checkmark' then
            local check_extent = math.min(rectangle.width, rectangle.height) * 0.4
            p:begin_path()
            p:move_to(center_x - check_extent, center_y - check_extent * 0.05)
            p:line_to(center_x - check_extent * 0.25, center_y + check_extent * 0.65)
            p:line_to(center_x + check_extent, center_y - check_extent * 0.65)
            p:stroke(painter_color, {width = math.max(1, check_extent * 0.18)})
        else
            -- Unknown icon, probably a good idea to nag the user
            p:begin_path()
            p:rect(ugui.internal.rect_to_painter_rect(rectangle))
            p:fill(ugui.internal.color_source_to_painter_color('#FF0000'))
        end
    end,

    ---Computes the segment data of rich text.
    ---@param text RichText The rich text.
    ---@param plaintext boolean? Whether the text is drawn without rich formatting. If nil, false is assumed.
    ---@param font_name string The font name to use for the text.
    ---@param font_size number The font size to use for the text.
    ---@return { segment_data: { segment: RichTextSegment, rectangle: UguiRect }[], size: UguiVector2  } # The computed rich text segment data.
    compute_rich_text = function(text, plaintext, font_name, font_size)
        if not text then
            return {segment_data = {}, size = {x = 0, y = 0}}
        end
        if text:find('[', 1, true) == nil then plaintext = true end

        if plaintext then
            local size = painter.measure_text(text, {family = font_name, size = font_size})
            return {
                segment_data = {
                    segment = {
                        type = 'text',
                        value = text,
                    },
                    rectangle = {
                        x = 0,
                        y = 0,
                        width = size.w,
                        height = size.h,
                    },
                },
                size = {
                    x = size.w,
                    y = size.h,
                },
            }
        end

        local segment_data = {}
        local icon_size = ugui.standard_styler.params.icon_size
        local x = 0
        local max_height = 0

        local segments = ugui.internal.parse_rich_text(text)

        -- 1. Compute untranslated (relative to {0,0}) and horizontally stacked rectangles for all segments.
        for i = 1, #segments do
            local segment = segments[i]
            local width
            local height

            if segment.type == 'icon' then
                width = icon_size
                height = icon_size
            elseif segment.type == 'text' then
                local size = painter.measure_text(segment.value, {family = font_name, size = font_size})
                width = size.w
                height = size.h
            else
                error(string.format("Unknown segment type '%s' encountered in measure_rich_text.", segment.type))
            end

            segment_data[#segment_data + 1] = {
                segment = segment,
                rectangle = {
                    x = x,
                    y = 0,
                    width = width,
                    height = height,
                },
            }
            x = x + width
            if height > max_height then
                max_height = height
            end
        end

        -- 2. Normalize all segments to the same max height.
        for i = 1, #segment_data do
            segment_data[i].rectangle.height = max_height
        end

        local total_width = x

        return {
            segment_data = segment_data,
            size = {
                x = total_width,
                y = max_height,
            },
        }
    end,

    ---Draws rich text with the specified parameters.
    ---@param params UguiDrawRichTextParams
    draw_rich_text = function(params)
        local rectangle = params.rectangle
        local align_x = params.align_x
        local align_y = params.align_y
        local text = params.text
        local color = params.color
        local plaintext = params.plaintext
        local font_name = params.font_name
        local font_size = params.font_size
        local wrap = params.wrap
        local fit = params.fit
        local clip = params.clip

        align_x = align_x or ugui.alignment.center
        align_y = align_y or ugui.alignment.center
        font_name = font_name or ugui.standard_styler.params.font_name
        font_size = font_size or ugui.standard_styler.params.font_size

        local clip_painter
        if clip then
            clip_painter = ugui.internal.painter
            clip_painter:save()
            clip_painter:clip(ugui.internal.rect_to_painter_rect(rectangle))
        end

        -- Plain text does not need rich-text parsing, whether forced or inferred from the content.
        if plaintext or text:find('[', 1, true) == nil then
            local p = ugui.internal.painter
            p:begin_path()
            p:text(text, ugui.internal.rect_to_painter_rect(rectangle), {
                family = font_name,
                size = font_size,
                weight = 400,
                slant = 'normal',
                fit = fit or false,
                wrap = wrap and 'word' or 'none',
                align_x = align_x == ugui.alignment.center and 'center' or
                    align_x == ugui.alignment['end'] and 'right' or
                    align_x == ugui.alignment.stretch and 'justify' or 'left',
                align_y = align_y == ugui.alignment.center and 'center' or
                    align_y == ugui.alignment['end'] and 'bottom' or 'top',
                antialiased = ugui.standard_styler.params.cleartype,
                overflow = 'visible',
                clip = false,
            })
            p:fill(ugui.internal.color_source_to_painter_color(color))
            if clip_painter then
                clip_painter:restore()
            end
            return
        end

        -- 1. Compute rich text segment data
        local computed = ugui.standard_styler.compute_rich_text(text, plaintext, font_name, font_size)
        local segment_data = computed.segment_data
        local total_width = computed.size.x

        if fit and total_width > 0 and computed.size.y > 0 then
            local scale = math.min(1, rectangle.width / total_width, rectangle.height / computed.size.y)
            if scale < 1 then
                font_size = font_size * scale
                total_width = total_width * scale
                for i = 1, #segment_data do
                    local data = segment_data[i]
                    data.rectangle.x = data.rectangle.x * scale
                    data.rectangle.width = data.rectangle.width * scale
                    data.rectangle.height = data.rectangle.height * scale
                end
            end
        end

        -- 2. Translate all segments to match the specified alignments
        if align_x == ugui.alignment.start then
            for i = 1, #segment_data do
                local data = segment_data[i]
                data.rectangle.x = data.rectangle.x + rectangle.x
            end
        elseif align_x == ugui.alignment.center then
            local x_offset = rectangle.x + (rectangle.width - total_width) / 2
            for i = 1, #segment_data do
                local data = segment_data[i]
                data.rectangle.x = data.rectangle.x + x_offset
            end
        elseif align_x == ugui.alignment['end'] then
            local x_offset = rectangle.x + rectangle.width - total_width
            for i = 1, #segment_data do
                local data = segment_data[i]
                data.rectangle.x = data.rectangle.x + x_offset
            end
        end

        if align_y == ugui.alignment.start then
            for i = 1, #segment_data do
                local data = segment_data[i]
                data.rectangle.y = data.rectangle.y + rectangle.y
            end
        elseif align_y == ugui.alignment.center then
            for i = 1, #segment_data do
                local data = segment_data[i]
                data.rectangle.y = data.rectangle.y + rectangle.y + rectangle.height / 2 - data.rectangle.height / 2
            end
        elseif align_y == ugui.alignment['end'] then
            for i = 1, #segment_data do
                local data = segment_data[i]
                data.rectangle.y = data.rectangle.y + rectangle.y + rectangle.height - data.rectangle.height
            end
        end

        -- 3. Draw the segments
        for i = 1, #segment_data do
            local data = segment_data[i]
            if data.segment.type == 'icon' then
                ugui.standard_styler.draw_icon(data.rectangle, data.segment.color or color,
                    data.segment.value)
            end
            if data.segment.type == 'text' then
                local p = ugui.internal.painter
                p:begin_path()
                p:text(data.segment.value, {
                    x = data.rectangle.x,
                    y = data.rectangle.y - 1,
                    w = data.rectangle.width + 1,
                    h = data.rectangle.height + 1,
                }, {
                    family = font_name,
                    size = font_size,
                    weight = 400,
                    slant = 'normal',
                    align_x = 'left',
                    align_y = 'top',
                    antialiased = ugui.standard_styler.params.cleartype,
                    overflow = 'clip',
                    clip = true,
                })
                p:fill(ugui.internal.color_source_to_painter_color(color))
            end
        end
        if clip_painter then
            clip_painter:restore()
        end
    end,

    ---Draws a raised frame with the specified parameters.
